const payload = $json.body ?? $json;
const toolCall = payload.message?.toolCallList?.[0] ?? payload.message?.toolCalls?.[0] ?? payload.toolCall ?? null;
const wrappedToolCall = payload.message?.toolWithToolCallList?.[0]?.toolCall ?? null;
const rawArgs = toolCall?.parameters ?? toolCall?.arguments ?? wrappedToolCall?.function?.parameters ?? wrappedToolCall?.function?.arguments ?? toolCall?.function?.arguments ?? payload.arguments ?? payload;
const details = [];
let args = rawArgs;
if (typeof rawArgs === 'string') {
  const trimmedArgs = rawArgs.trim();
  if (!trimmedArgs) {
    args = {};
  } else {
    try {
      args = JSON.parse(trimmedArgs);
    } catch (error) {
      details.push(`Invalid JSON arguments: ${error.message}`);
      args = {};
    }
  }
}
if (!args || typeof args !== 'object' || Array.isArray(args)) {
  details.push('Request arguments must be a JSON object');
  args = {};
}
const parseWholeNumber = (value, fallback, minimum = 1, maximum = Number.MAX_SAFE_INTEGER) => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(Math.max(Math.trunc(parsed), minimum), maximum);
};
const timezone = args.timezone || $env.CLINIC_TIMEZONE || 'Europe/Warsaw';
const durationMinutes = parseWholeNumber(args.service?.durationMinutes, parseWholeNumber($env.DEFAULT_APPOINTMENT_DURATION_MINUTES || 30, 30), 1, 480);
const rawRequestedTime = typeof args.requestedTime === 'string' ? args.requestedTime.trim() : '';
const requestedTime = rawRequestedTime || null;
const allowedTimePreferences = new Set(['morning', 'afternoon', 'evening', 'first_available', 'specific_time']);
const requestedTimePreference = typeof args.timePreference === 'string' ? args.timePreference : null;
const rawTimePreference = requestedTimePreference || (requestedTime ? 'specific_time' : 'first_available');
const timePreference = allowedTimePreferences.has(rawTimePreference) ? rawTimePreference : 'first_available';
const limit = parseWholeNumber(args.limit ?? $env.DEFAULT_SLOT_SEARCH_LIMIT ?? 3, 3, 1, 5);
const incrementMinutes = parseWholeNumber($env.DEFAULT_SLOT_INCREMENT_MINUTES || 30, 30, 1, 240);
const maxSearchDays = 14;
const workingStart = $env.CLINIC_WORKING_HOURS_START || '08:00';
const workingEnd = $env.CLINIC_WORKING_HOURS_END || '18:00';
const getZonedParts = (date, timeZone) => Object.fromEntries(new Intl.DateTimeFormat('sv-SE', {
  timeZone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hourCycle: 'h23'
}).formatToParts(date).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
const getOffsetMinutes = (date, timeZone) => {
  const parts = getZonedParts(date, timeZone);
  const zonedAsUtc = Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day), Number(parts.hour), Number(parts.minute), Number(parts.second));
  return Math.round((zonedAsUtc - date.getTime()) / 60000);
};
const zonedDateTimeToDate = (dateText, timeText, timeZone) => {
  const [year, month, day] = dateText.split('-').map(Number);
  const [hour, minute] = timeText.split(':').map(Number);
  let date = new Date(Date.UTC(year, month - 1, day, hour, minute, 0));
  for (let index = 0; index < 2; index += 1) {
    const offsetMinutes = getOffsetMinutes(date, timeZone);
    date = new Date(Date.UTC(year, month - 1, day, hour, minute, 0) - offsetMinutes * 60000);
  }
  return date;
};
const formatDateText = (date, timeZone) => {
  const parts = getZonedParts(date, timeZone);
  return [parts.year, parts.month, parts.day].join('-');
};
const addDays = (dateText, days) => {
  const [year, month, day] = dateText.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day + days, 12, 0, 0));
  return date.toISOString().slice(0, 10);
};
const timeToMinutes = (timeText) => {
  const [hour, minute] = timeText.split(':').map(Number);
  return (hour * 60) + minute;
};
const ceilTimeText = (timeText, stepMinutes) => {
  const totalMinutes = timeToMinutes(timeText);
  const roundedMinutes = Math.ceil(totalMinutes / stepMinutes) * stepMinutes;
  const hour = String(Math.floor(roundedMinutes / 60)).padStart(2, '0');
  const minute = String(roundedMinutes % 60).padStart(2, '0');
  return hour + ':' + minute;
};
const todayDate = formatDateText(new Date(), timezone);
const requestedDate = typeof args.requestedDate === 'string' && args.requestedDate.trim()
  ? args.requestedDate.trim()
  : (timePreference === 'first_available' ? todayDate : null);
const searchDays = timePreference === 'first_available'
  ? parseWholeNumber(args.searchDays ?? $env.DEFAULT_FIRST_AVAILABLE_SEARCH_DAYS ?? 5, 5, 1, maxSearchDays)
  : 1;
if (!args.service?.id) details.push('service.id is required');
if (!requestedDate) details.push('requestedDate is required unless timePreference is first_available');
if (!timezone) details.push('timezone is required');
if (requestedTimePreference && !allowedTimePreferences.has(requestedTimePreference)) details.push('timePreference is invalid');
if (timePreference === 'specific_time' && !requestedTime) details.push('requestedTime is required when timePreference is specific_time');
const windows = {
  morning: ['08:00', '12:00'],
  afternoon: ['12:00', '16:00'],
  evening: ['16:00', '19:00'],
  first_available: [workingStart, workingEnd],
  specific_time: [requestedTime || workingStart, requestedTime || workingStart]
};
const [windowStartTime, windowEndTime] = windows[timePreference] || windows.first_available;
let windowStart = null;
let windowEnd = null;
if (requestedDate) {
  let firstSearchDate = requestedDate;
  let startDate = zonedDateTimeToDate(firstSearchDate, windowStartTime, timezone);
  if (timePreference === 'first_available' && requestedDate === todayDate) {
    const nowParts = getZonedParts(new Date(), timezone);
    const nowMinutes = timeToMinutes(nowParts.hour + ':' + nowParts.minute);
    const workingStartMinutes = timeToMinutes(workingStart);
    const workingEndMinutes = timeToMinutes(workingEnd);
    if (nowMinutes >= workingEndMinutes) {
      firstSearchDate = addDays(todayDate, 1);
      startDate = zonedDateTimeToDate(firstSearchDate, workingStart, timezone);
    } else if (nowMinutes > workingStartMinutes) {
      startDate = zonedDateTimeToDate(todayDate, ceilTimeText(nowParts.hour + ':' + nowParts.minute, incrementMinutes), timezone);
    }
  }
  const lastSearchDate = addDays(firstSearchDate, searchDays - 1);
  const endDate = timePreference === 'specific_time'
    ? new Date(startDate.getTime() + durationMinutes * 60000)
    : zonedDateTimeToDate(lastSearchDate, windowEndTime, timezone);
  if (!Number.isNaN(startDate.getTime()) && !Number.isNaN(endDate.getTime()) && endDate > startDate) {
    windowStart = startDate.toISOString();
    windowEnd = endDate.toISOString();
  }
}
return [{ json: {
  ok: details.length === 0,
  toolCallId: toolCall?.id || wrappedToolCall?.id || payload.toolCallId || null,
  requestId: args.requestId || payload.requestId || null,
  calendarId: args.calendarId || $env.GOOGLE_CALENDAR_ID || 'primary',
  timezone,
  service: args.service || null,
  requestedDate,
  requestedTime,
  timePreference,
  durationMinutes,
  limit,
  incrementMinutes,
  searchDays,
  workingStart,
  workingEnd,
  windowStart,
  windowEnd,
  patient: args.patient || null,
  validationErrors: details
} }];

const config = $('Parse Request').first().json;
const events = $input.all().map((item) => item.json).filter((item) => item.start || item.end);
const incrementMinutes = Number(config.incrementMinutes || $env.DEFAULT_SLOT_INCREMENT_MINUTES || 30);
const durationMinutes = Number(config.durationMinutes || 30);
const limit = Number(config.limit || 3);
const rangeStart = new Date(config.windowStart);
const rangeEnd = new Date(config.windowEnd);
const getZonedParts = (date, timeZone) => Object.fromEntries(new Intl.DateTimeFormat('sv-SE', {
  timeZone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hourCycle: 'h23'
}).formatToParts(date).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
const formatZonedDateTime = (date, timeZone) => {
  const parts = getZonedParts(date, timeZone);
  const zonedAsUtc = Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day), Number(parts.hour), Number(parts.minute), Number(parts.second));
  const offsetMinutes = Math.round((zonedAsUtc - date.getTime()) / 60000);
  const sign = offsetMinutes >= 0 ? '+' : '-';
  const absoluteOffset = Math.abs(offsetMinutes);
  const offsetHours = String(Math.floor(absoluteOffset / 60)).padStart(2, '0');
  const offsetRemainder = String(absoluteOffset % 60).padStart(2, '0');
  return parts.year + '-' + parts.month + '-' + parts.day + 'T' + parts.hour + ':' + parts.minute + ':' + parts.second + sign + offsetHours + ':' + offsetRemainder;
};
const timeToMinutes = (timeText) => {
  const [hour, minute] = timeText.split(':').map(Number);
  return (hour * 60) + minute;
};
const workingStartMinutes = timeToMinutes(config.workingStart || '08:00');
const workingEndMinutes = timeToMinutes(config.workingEnd || '18:00');
const busy = events.map((event) => ({
  start: new Date(event.start?.dateTime || event.start || event.dateTime || rangeStart),
  end: new Date(event.end?.dateTime || event.end || event.dateTime || rangeStart)
})).filter((event) => !Number.isNaN(event.start.getTime()) && !Number.isNaN(event.end.getTime()));
const slots = [];
for (let cursor = new Date(rangeStart); cursor < rangeEnd; cursor = new Date(cursor.getTime() + incrementMinutes * 60000)) {
  const slotStart = new Date(cursor);
  const slotEnd = new Date(cursor.getTime() + durationMinutes * 60000);
  if (slotEnd > rangeEnd) break;
  const slotStartParts = getZonedParts(slotStart, config.timezone);
  const slotEndParts = getZonedParts(slotEnd, config.timezone);
  const slotStartDate = [slotStartParts.year, slotStartParts.month, slotStartParts.day].join('-');
  const slotEndDate = [slotEndParts.year, slotEndParts.month, slotEndParts.day].join('-');
  const slotStartMinutes = timeToMinutes(slotStartParts.hour + ':' + slotStartParts.minute);
  const slotEndMinutes = timeToMinutes(slotEndParts.hour + ':' + slotEndParts.minute);
  if (slotStartDate !== slotEndDate) continue;
  if (slotStartMinutes < workingStartMinutes) continue;
  if (slotEndMinutes > workingEndMinutes) continue;
  const overlaps = busy.some((event) => slotStart < event.end && slotEnd > event.start);
  if (overlaps) continue;
  const label = new Intl.DateTimeFormat('pl-PL', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: config.timezone
  }).format(slotStart);
  slots.push({
    start: formatZonedDateTime(slotStart, config.timezone),
    end: formatZonedDateTime(slotEnd, config.timezone),
    label,
    calendarId: config.calendarId
  });
  if (slots.length >= limit) break;
}
return [{ json: {
  requestId: config.requestId,
  toolCallId: config.toolCallId,
  available: slots.length > 0,
  timezone: config.timezone,
  normalizedRequest: {
    serviceId: config.service.id,
    durationMinutes: config.durationMinutes,
    windowStart: formatZonedDateTime(rangeStart, config.timezone),
    windowEnd: formatZonedDateTime(rangeEnd, config.timezone),
    requestedDate: config.requestedDate,
    requestedTime: config.requestedTime,
    timePreference: config.timePreference,
    searchDays: config.searchDays
  },
  slots,
  message: slots.length > 0
    ? 'Znalazlam najblizsze dostepne terminy.'
    : 'Nie widze wolnych terminow w podanym zakresie.'
} }];

const result = $json;
const body = result.toolCallId
  ? { results: [{ toolCallId: result.toolCallId, result: { requestId: result.requestId, available: result.available, timezone: result.timezone, normalizedRequest: result.normalizedRequest, slots: result.slots, message: result.message } }] }
  : { requestId: result.requestId, available: result.available, timezone: result.timezone, normalizedRequest: result.normalizedRequest, slots: result.slots, message: result.message };
return [{ json: body }];

const result = {
  requestId: $json.requestId,
  available: false,
  timezone: $json.timezone,
  slots: [],
  message: 'Brakuje danych do sprawdzenia dostepnosci.',
  error: {
    code: 'VALIDATION_ERROR',
    details: $json.validationErrors || []
  }
};
const body = $json.toolCallId
  ? { results: [{ toolCallId: $json.toolCallId, result }] }
  : result;
return [{ json: body }];
